/**
 * WHAT A SCREEN IS ABOUT, AS AN OBJECT.
 *
 * One painted still life per destination — the crate for Supply, the pegboard
 * for Hardware, the apron rack for the Crew. They answer "where am I" faster
 * than the heading does, and they cost nothing to add to a head that already
 * has a picture-sized gap in it.
 */
export type PanelMarkName =
  | 'supply'
  | 'hardware'
  | 'crew'
  | 'codex'
  | 'cellar'
  | 'orders'
  | 'contracts'
  | 'books'
  | 'bench'
  | 'inoculation'
  | 'inspector'
  | 'press'
  | 'recipe'
  | 'first'
  | 'crock'
  | 'door'
  | 'underground'
  | 'kojiroom';

